from pathlib import Path
import base64, hashlib, subprocess, zlib
DATA = """"""
patch = zlib.decompress(base64.b64decode(DATA, validate=True))
assert hashlib.sha256(patch).hexdigest() == '5837f0a1a5c7ee9766dcda61fa1a447d31bd55ea4f9837bedf59b2f75faf8eac'
subprocess.run(['git','apply','--index','--whitespace=nowarn','-'],input=patch,check=True)
print('Applied locally verified layout and native automation corrections.')
